//! PRD-mcphost-audit-export-tamper-evident
//! AC4 (P0) — Given `tests/fixtures/audit_vectors.json` regenerated by the
//! Rust test, When the Python test loads it, Then every vector verifies;
//! Given the Rust canonical form changed in a test copy, Then the vector file
//! differs and the Python test fails on it.

use crate::audx_ac03_offline_verifier_ok_and_fail_lines::scratch_dir;
use mcphost::audit_export::{RawAuditRow, canonical_json, chain_with, root_of, signed_message};
use mcphost::rowpolicy::audit::GENESIS_HASH;
use serde_json::{Value, json};
use std::path::Path;
use std::process::Command;

const ROOT: &str = env!("CARGO_MANIFEST_DIR");

/// The five fixed rows the vectors chain: all three tables, a `null` detail,
/// nested detail, quotes, control characters and non-ASCII text.
fn vector_rows() -> Vec<RawAuditRow> {
    let row = |ts, table, id, subject: &str, action: &str, detail: Value| RawAuditRow {
        ts,
        table,
        id,
        subject: subject.to_string(),
        action: action.to_string(),
        detail,
    };
    vec![
        row(1_760_000_000, "audit_chain", 1, "alice", "filtered_read:sql", json!({"applied": "region = 'eu'", "returned_count": 5, "withheld_count": null, "stored_hash": "ab"})),
        row(1_760_000_000, "oauth_audit", 1, "", "token", json!({"client_id": "cid", "scopes": "read write", "reason": null})),
        row(1_760_000_001, "tenant_audit", 1, "bob", "key_rotate", json!("détail \"q\"\n\ttab \u{1} 日本語 🔑")),
        row(1_760_000_002, "tenant_audit", 2, "bob", "offboard", Value::Null),
        row(1_760_000_003, "audit_chain", 2, "ünï", "filtered_read:docs", json!({"applied": "a\\b", "returned_count": 0, "withheld_count": 3, "stored_hash": "cd"})),
    ]
}

/// The deterministic part of the vector file for one canonical form.
fn vectors_with(canon: fn(&Value) -> String) -> Value {
    let lines = chain_with(vector_rows(), canon);
    let line_values: Vec<Value> = lines.iter().map(|l| l.to_value()).collect();
    let canonical: Vec<String> = lines
        .iter()
        .map(|l| {
            let mut body = l.to_value();
            body.as_object_mut().expect("object").remove("hash");
            canon(&body)
        })
        .collect();
    let root = root_of(&lines);
    json!({
        "genesis": GENESIS_HASH,
        "lines": line_values,
        "canonical": canonical,
        "root_hash": root,
        "rows": lines.len(),
        "signed_message": signed_message(&root, lines.len()),
    })
}

fn python_test(vectors: &Path) -> bool {
    Command::new("python3")
        .arg("-I")
        .arg(Path::new(ROOT).join("tests/test_audit_vectors.py"))
        .env("AUDIT_VECTORS", vectors)
        .output()
        .expect("run test_audit_vectors.py")
        .status
        .success()
}

/// Does `file`'s signature still verify under the key it embeds?
fn signature_still_verifies(file: &Value) -> bool {
    let (Some(jwk), Some(sig), Some(msg)) =
        (file["jwks"]["keys"].get(0), file["trailer"]["signature"].as_str(), file["signed_message"].as_str())
    else {
        return false;
    };
    let (Some(x), Some(y)) = (jwk["x"].as_str(), jwk["y"].as_str()) else { return false };
    jsonwebtoken::DecodingKey::from_ec_components(x, y)
        .and_then(|key| jsonwebtoken::crypto::verify(sig, msg.as_bytes(), &key, jsonwebtoken::Algorithm::ES256))
        .unwrap_or(false)
}

/// Regenerates `tests/fixtures/audit_vectors.json` when its deterministic part
/// (or its signature) is stale; ES256 signing is randomised, so an up-to-date
/// file is left byte-for-byte alone.
fn regenerate_if_stale(path: &Path, fresh: &Value) {
    let keys = ["genesis", "lines", "canonical", "root_hash", "rows", "signed_message"];
    if let Ok(text) = std::fs::read_to_string(path)
        && let Ok(committed) = serde_json::from_str::<Value>(&text)
        && keys.iter().all(|k| committed[*k] == fresh[*k])
        && signature_still_verifies(&committed)
    {
        return;
    }
    let dir = scratch_dir("ac04-key");
    let key = mcphost::authz::AuthzSigningKey::load_or_generate(&dir).expect("signing key");
    let root = fresh["root_hash"].as_str().expect("root");
    let rows = fresh["rows"].as_u64().expect("rows") as usize;
    let signature = key.sign_bytes(signed_message(root, rows).as_bytes()).expect("sign");
    let mut file = fresh.clone();
    file["jwks"] = key.jwks_document();
    file["header"] = json!({"tenant_ns": "t_vectors", "since": null, "until": null, "host_version": "vectors", "kid": key.kid});
    file["trailer"] = json!({"root_hash": root, "rows": rows, "signature": signature, "kid": key.kid});
    std::fs::write(path, serde_json::to_string_pretty(&file).expect("json") + "\n").expect("write vectors");
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn audx_ac04_python_verifies_the_rust_generated_vectors_and_fails_on_a_changed_canonical_form() {
    let path = Path::new(ROOT).join("tests/fixtures/audit_vectors.json");
    let fresh = vectors_with(canonical_json);
    regenerate_if_stale(&path, &fresh);
    let committed: Value = serde_json::from_str(&std::fs::read_to_string(&path).expect("vectors")).expect("json");
    assert_eq!(committed["lines"].as_array().map(Vec::len), Some(5));

    // Every vector verifies in Python, against the file the Rust test just made current.
    assert!(python_test(&path), "the Python vector test must pass on the generated file");

    // The Rust canonical form changed in a test copy (a space after each comma):
    // the vector file differs, and the Python test fails on it.
    let spaced: fn(&Value) -> String = |v| canonical_json(v).replace("\",\"", "\", \"");
    let changed = vectors_with(spaced);
    assert_ne!(changed["lines"], committed["lines"], "the changed canonical form changes the vector file");
    assert_ne!(changed["root_hash"], committed["root_hash"]);
    let mut copy = committed.clone();
    for k in ["lines", "canonical", "root_hash", "signed_message"] {
        copy[k] = changed[k].clone();
    }
    let dir = scratch_dir("ac04");
    let copy_path = dir.join("audit_vectors.json");
    std::fs::write(&copy_path, serde_json::to_string_pretty(&copy).expect("json")).expect("write copy");
    assert!(!python_test(&copy_path), "the Python test must fail on vectors made with a different canonical form");
    let _ = std::fs::remove_dir_all(dir);
}
